// The full command surface. Names are fixed from F0 so usage, dispatch, and
// tests are stable; handlers arrive feature by feature. The tier (above) keeps
// dev and unfinished commands out of the release `--help` (see print_usage).
// Listed release-first, then dev, then hidden -- dispatch is by name, so the
// order is purely the display order.
constexpr Subcommand kSubcommands[] = {
    {"run", "run one simulation (--model fast|cycle|hybrid)", Tier::Release},
    {"list", "list models|engines", Tier::Release},
    {"build", "build artifacts (qemu, vsim, plugin, simpoint, fixtures, driver)",
     Tier::Dev},
    {"test", "run the end-to-end suite", Tier::Dev},
    {"doctor", "check environment health", Tier::Dev},
    {"state-diff", "compare two drained state files (oracle vs vsim)",
     Tier::Dev},
    {"profile", "profile a workload into a basic-block vector", Tier::Hidden},
    {"cluster", "cluster a BBV into SimPoint phases", Tier::Hidden},
